using System;using Ashfall.Core;using Ashfall.Modules.WeaponHandling;
namespace Ashfall.Integration.Playable.HandsWeapons {
 public sealed class R24M60Shot {
  public readonly string InstanceId;public readonly CommandContext Command;public readonly HandlingSnapshot Before,After;public readonly R23ShotPose Pose;public readonly bool Supported;
  internal R24M60Shot(string id,CommandContext c,HandlingSnapshot before,HandlingSnapshot after,R23ShotPose pose,bool support){InstanceId=id;Command=c;Before=before;After=after;Pose=pose;Supported=support;}
 }
 public sealed class R24M60Owner {
  sealed class Initial:IWeaponLifetimeAuthority {readonly CommandContext creation;readonly string id;readonly int capacity;internal Initial(CommandContext c,string i,int count){creation=c;id=i;capacity=count;}public RuleResult AuthorizeNew(CommandContext c,string instance,WeaponMechanism m,int rounds){return c.SessionId==creation.SessionId&&c.ActorId==creation.ActorId&&c.CommandId==creation.CommandId&&c.Tick==creation.Tick&&c.AuthorityEpoch==creation.AuthorityEpoch&&c.IsAuthority&&instance==id&&m==WeaponMechanism.ServiceRifle&&rounds==capacity?RuleResult.Accept():RuleResult.Reject("source M60 initial entitlement");}public RuleResult AuthorizeRestore(CommandContext c,string i,string actor,long epoch){return RuleResult.Reject("retained local M60 owner");}}
  readonly WeaponHandling weapon;readonly IRevisionedAmmoReserve reserve;bool retired;
  internal bool ReconcileNetworkAmmo(int rounds){return weapon.ReconcileNetworkMagazine(rounds);}
public string InstanceId{get;private set;}public int Capacity{get;private set;}public int Reserve{get{return reserve.Available;}}public R24M60Stage Stage{get{return weapon.M60Stage;}}public int Loaded{get{return Stage==R24M60Stage.Ready?weapon.Snapshot.Loaded:weapon.Snapshot.Seated;}}public int SpoolShots{get{return weapon.M60SpoolShots;}}public bool BeltFed{get{return weapon.M60BeltFed;}}public bool ReloadGripInProgress{get{return weapon.M60Contact||Stage==R24M60Stage.HoldingBox;}}public bool Contact{get{return weapon.M60Contact;}}public float MotionProgress{get{return weapon.M60Progress;}}public R24M60Stage MotionStage{get{return weapon.M60MotionStage;}}
  public HandlingSnapshot Snapshot{get{var s=weapon.Snapshot;s.ClaimsSupport|=Stage!=R24M60Stage.Ready;if(Stage==R24M60Stage.Ready)s.Seated=0;return s;}}
  public bool GripToggle{get{return weapon.GripToggle;}set{if(weapon.GripToggle!=value){weapon.GripToggle=value;SuspendControls();}}}public string ReloadCue{get;private set;}
  public R24M60Owner(CommandContext creation,string instance,IRevisionedAmmoReserve rifle,IAuthorityGate authority,int stars=1){if(rifle==null||authority==null||String.IsNullOrEmpty(instance)||instance.Length>128)throw new ArgumentException("M60 actual lifetime/finite reserve required");Capacity=R24M60Definition.Capacity(stars);InstanceId=instance;reserve=rifle;var definition=SourceRifleDefinition.M60.WithRarity(Capacity,27,33);var ledger=new WeaponLifetimes(creation.SessionId,new Initial(creation,instance,Capacity));WeaponHandling active;var r=ledger.CreateSourceRifle(creation,instance,definition,rifle,authority,out active);if(!r.Accepted)throw new InvalidOperationException(r.Reason);weapon=active;weapon.InitializeM60();weapon.SuspendM60Controls();}
  public void SuspendControls(){weapon.SuspendM60Controls();ReloadCue=null;}public void Retire(){SuspendControls();retired=true;}
  public RuleResult Apply(CommandContext command,HandlingAction action,HandlingInput input,R23ShotPose pose,out R24M60Shot shot){shot=null;ReloadCue=null;if(retired)return RuleResult.Reject("retired M60 instance");if(input.Enabled&&!input.Paused&&input.PrimaryTracked&&!input.PrimaryClimbing&&!input.HeadObstructed&&input.Trigger&&!pose.Valid)return RuleResult.Reject("finite accepted M60 muzzle frame required");var before=Snapshot;var stage=Stage;var r=weapon.ApplyM60(command,action,input);var after=Snapshot;if(after.Shots==before.Shots+1)shot=new R24M60Shot(InstanceId,command,before,after,pose,weapon.M60LastShotSupported);if(Stage!=stage)ReloadCue=Stage==R24M60Stage.BoxRemoved?"mag_eject":Stage==R24M60Stage.HoldingBox?"pouch":Stage==R24M60Stage.NeedsFeed||Stage==R24M60Stage.BoxSeated?"mag_insert":Stage==R24M60Stage.NeedsCharge?"close":Stage==R24M60Stage.Ready?"bolt":Stage==R24M60Stage.CoverOpen?"open":null;return r;}
 }
}
